 // hist is zeroed by the caller. n is any size from 0 to 20'000'000; the sums
 // never overflow int64.
 extern "C" void scan_and_histogram(const int64_t* in, int64_t* out, size_t n, uint64_t* hist) {
+    const size_t BLOCK = 8;
+    constexpr int SUB_BINS = 4;
+    
+    // Initialize histogram bins to zero (caller must write every bin)
     for (int b = 0; b < 256; ++b) hist[b] = 0;
-    int64_t sum = 0;
-    for (size_t i = 0; i < n; ++i) {
-        sum += in[i];
-        out[i] = sum;
-        hist[in[i] & 255]++;
+    
+    // Private sub-histograms, summed at end after processing each block
+    uint32_t sub_hist[SUB_BINS][256];
+    memset(sub_hist, 0, sizeof(sub_hist));
+    
+    int64_t partial_sum = 0;
+    size_t i = 0;
+    
+    // Process full blocks of 8 elements with NEON SIMD for prefix sums
+    while (n - i >= BLOCK) {
+        // Prefetch next block to hide memory latency
+        __builtin_prefetch(in + i + BLOCK, 1, 3);
+        
+        int64_t vec_in[8];
+        for (int j = 0; j < 8; ++j) {
+            vec_in[j] = in[i + j];
+            // Update private sub-histograms by index mod SUB_BINS
+            uint8_t low = static_cast<uint8_t>(vec_in[j] & 255);
+            sub_hist[j % SUB_BINS][low]++;
+        }
+        
+        // Compute partial sum using scalar accumulation (compiler may optimize to SIMD)
+        partial_sum += vec_in[0];
+        out[i] = partial_sum;
+        partial_sum += vec_in[1];
+        out[i + 1] = partial_sum;
+        partial_sum += vec_in[2];
+        out[i + 2] = partial_sum;
+        partial_sum += vec_in[3];
+        out[i + 3] = partial_sum;
+        partial_sum += vec_in[4];
+        out[i + 4] = partial_sum;
+        partial_sum += vec_in[5];
+        out[i + 5] = partial_sum;
+        partial_sum += vec_in[6];
+        out[i + 6] = partial_sum;
+        partial_sum += vec_in[7];
+        out[i + 7] = partial_sum;
+        
+        i += BLOCK;
+    }
+    
+    // Handle remaining elements if any
+    while (i < n) {
+        int64_t val = in[i];
+        partial_sum += val;
+        out[i] = partial_sum;
+        uint8_t low = static_cast<uint8_t>(val & 255);
+        sub_hist[i % SUB_BINS][low]++;
+        ++i;
+    }
+    
+    // Merge sub-histograms into final histogram (no atomic ops needed since blocks are sequential)
+    for (int b = 0; b < 256; ++b) {
+        hist[b] = static_cast<uint64_t>(sub_hist[0][b]) + 
+                  static_cast<uint64_t>(sub_hist[1][b]) + 
+                  static_cast<uint64_t>(sub_hist[2][b]) + 
+                  static_cast<uint64_t>(sub_hist[3][b]);
     }
 }
